use crate::storage::Database;
use rusqlite::params;
use serde_json::{json,Value};
use windows_sys::Win32::UI::WindowsAndMessaging::SystemParametersInfoW;
// Documented SPI user preferences. No direct registry writes.
pub const IDS:[&str;6]=["visual.client_animation","visual.menu_animation","visual.tooltip_animation","visual.combobox_animation","visual.listbox_scrolling","visual.selection_fade"];
pub fn inventory()->Value{let mut row=serde_json::Map::new();let mut errors=serde_json::Map::new();for(id,key)in IDS.into_iter().zip(["ClientAnimation","MenuAnimation","TooltipAnimation","ComboboxAnimation","ListboxScrolling","SelectionFade"]){match read(id){Ok(value)=>{row.insert(key.into(),json!(value));},Err(error)=>{row.insert(key.into(),Value::Null);errors.insert(key.into(),json!(error));}}}row.insert("Errors".into(),Value::Object(errors));json!([row])}
pub fn definition(id:&str)->Result<(u32,u32,u32),String>{match id {
 "visual.client_animation"=>Ok((0x1042,0x1043,0)),
 "visual.menu_animation"=>Ok((0x1002,0x1003,0)),
 "visual.tooltip_animation"=>Ok((0x1016,0x1017,0)),
 "visual.combobox_animation"=>Ok((0x1004,0x1005,0)),
 "visual.listbox_scrolling"=>Ok((0x1006,0x1007,0)),
 "visual.selection_fade"=>Ok((0x1014,0x1015,0)),
 _=>Err("Alteração não implementada ou não permitida".into())}}
pub fn read(id:&str)->Result<Option<u32>,String>{let(get,_,_)=definition(id)?;let mut value:i32=0;let ok=unsafe{SystemParametersInfoW(get,0,&mut value as *mut _ as _,0)};if ok==0{return Err(std::io::Error::last_os_error().to_string())}Ok(Some(u32::from(value!=0)))}
fn write(id:&str,value:Option<u32>)->Result<(),String>{let(_,set,_)=definition(id)?;let value=value.filter(|v|*v<=1).ok_or("Preferência inválida")?;let ok=unsafe{SystemParametersInfoW(set,0,value as usize as *mut std::ffi::c_void,3)};if ok==0{return Err(std::io::Error::last_os_error().to_string())}if read(id)?!=Some(value){return Err("A verificação da preferência falhou".into())}Ok(())}
pub fn preview(ids:Vec<String>)->Result<Value,String>{if ids.is_empty()||ids.len()>IDS.len(){return Err("Selecione entre uma e seis alterações".into())}let mut result=Vec::new();for id in ids{let(_,_,new)=definition(&id)?;let old=read(&id)?;if old!=Some(new){result.push(json!({"id":id,"previous":old,"next":new,"admin":false,"restart":"Algumas aplicações podem exigir reinício","benefit":"Preferência do utilizador; ganhos de FPS não garantidos"}));}}Ok(json!(result))}
trait Preferences {fn read(&self,id:&str)->Result<Option<u32>,String>;fn write(&self,id:&str,value:Option<u32>)->Result<(),String>;}
struct WindowsPreferences;
impl Preferences for WindowsPreferences {fn read(&self,id:&str)->Result<Option<u32>,String>{read(id)}fn write(&self,id:&str,value:Option<u32>)->Result<(),String>{write(id,value)}}
pub fn apply(db:&Database,id:&str,expected:Option<u32>)->Result<Value,String>{apply_with(db,id,expected,&WindowsPreferences)}
fn apply_with(db:&Database,id:&str,expected:Option<u32>,store:&dyn Preferences)->Result<Value,String>{let(_,_,new)=definition(id)?;let old=store.read(id)?;if old!=expected{return Err("A configuração mudou desde a pré-visualização. Volte a analisar.".into())}if old==Some(new){return Ok(json!({"status":"unchanged"}))}let previous=serde_json::to_string(&old).map_err(|e|e.to_string())?;let conn=db.0.lock().map_err(|e|e.to_string())?;conn.execute("INSERT INTO changes(optimization_id,previous_value,new_value,status) VALUES(?1,?2,?3,'pending')",params![id,previous,new.to_string()]).map_err(|e|e.to_string())?;let row=conn.last_insert_rowid();drop(conn);let result=store.write(id,Some(new)).and_then(|_|if store.read(id)?==Some(new){Ok(())}else{Err("Verificação falhou".into())});let(status,error)=match &result{Ok(_)=>("applied",None),Err(e)=>("failed",Some(e.clone()))};db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status=?1,error=?2 WHERE id=?3",params![status,error,row]).map_err(|e|e.to_string())?;db.log("optimization.apply",&json!({"id":id,"change":row,"status":status,"error":error}).to_string())?;result?;Ok(json!({"id":row,"status":status,"verified":true}))}
pub fn restore(db:&Database,change:i64)->Result<Value,String>{restore_with(db,change,&WindowsPreferences)}
fn restore_with(db:&Database,change:i64,store:&dyn Preferences)->Result<Value,String>{let conn=db.0.lock().map_err(|e|e.to_string())?;let(id,previous,new,status):(String,String,String,String)=conn.query_row("SELECT optimization_id,previous_value,new_value,status FROM changes WHERE id=?1",[change],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).map_err(|e|e.to_string())?;let newer:i64=conn.query_row("SELECT COUNT(*) FROM changes WHERE optimization_id=?1 AND id>?2 AND status IN ('applied','pending','failed')",params![id,change],|r|r.get(0)).map_err(|e|e.to_string())?;drop(conn);if newer>0{return Err("Restaure primeiro a alteração mais recente desta preferência".into())}if status=="restored"{return Ok(json!({"status":"restored"}))}let old:Option<u32>=serde_json::from_str(&previous).map_err(|e|e.to_string())?;let applied:u32=new.parse::<u32>().map_err(|e|e.to_string())?;let current=store.read(&id)?;if current!=Some(applied)&&current!=old{return Err("Conflito: a configuração foi alterada fora da aplicação. Nada foi sobrescrito.".into())}store.write(&id,old)?;if store.read(&id)?!=old{return Err("Restauro não verificado".into())}db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status='restored',error=NULL WHERE id=?1",[change]).map_err(|e|e.to_string())?;db.log("optimization.restore",&change.to_string())?;Ok(json!({"status":"restored","verified":true}))}
#[cfg(test)]
mod tests {
 use super::*;use std::sync::Mutex;use std::path::Path;
 struct Fake {value:Mutex<Option<u32>>,deny:Mutex<bool>,ignore:bool}
 impl Fake {fn new()->Self{Self{value:Mutex::new(Some(1)),deny:Mutex::new(false),ignore:false}}}
 impl Preferences for Fake {fn read(&self,_:&str)->Result<Option<u32>,String>{Ok(*self.value.lock().unwrap())}fn write(&self,_:&str,value:Option<u32>)->Result<(),String>{if *self.deny.lock().unwrap(){return Err("Access denied".into())}if !self.ignore{*self.value.lock().unwrap()=value;}Ok(())}}
 #[test]fn explicit_allowlist(){assert!(definition("disable_defender").is_err());assert!(definition("arbitrary.path").is_err());assert_eq!(definition("visual.menu_animation").unwrap().2,0);assert!(preview(vec![]).is_err());}
 #[test]fn apply_verify_restore_and_idempotence(){let db=Database::open(Path::new(":memory:")).unwrap();let store=Fake::new();let result=apply_with(&db,"visual.menu_animation",Some(1),&store).unwrap();assert_eq!(store.read("").unwrap(),Some(0));assert_eq!(apply_with(&db,"visual.menu_animation",Some(0),&store).unwrap()["status"],"unchanged");assert_eq!(db.list("changes").unwrap().as_array().unwrap().len(),1);let id=result["id"].as_i64().unwrap();restore_with(&db,id,&store).unwrap();assert_eq!(store.read("").unwrap(),Some(1));restore_with(&db,id,&store).unwrap();}
 #[test]fn denied_permission_is_audited_and_original_preserved(){let db=Database::open(Path::new(":memory:")).unwrap();let store=Fake::new();*store.deny.lock().unwrap()=true;assert!(apply_with(&db,"visual.menu_animation",Some(1),&store).is_err());assert_eq!(store.read("").unwrap(),Some(1));let rows=db.list("changes").unwrap();assert_eq!(rows[0]["status"],"failed");assert_eq!(rows[0]["previous_value"],"1");}
 #[test]fn verification_failure_does_not_claim_success(){let db=Database::open(Path::new(":memory:")).unwrap();let mut store=Fake::new();store.ignore=true;assert!(apply_with(&db,"visual.menu_animation",Some(1),&store).is_err());assert_eq!(db.list("changes").unwrap()[0]["status"],"failed");}
 #[test]fn stale_preview_does_not_write(){let db=Database::open(Path::new(":memory:")).unwrap();let store=Fake::new();assert!(apply_with(&db,"visual.menu_animation",Some(0),&store).is_err());assert_eq!(db.list("changes").unwrap().as_array().unwrap().len(),0);}
 #[test]fn interrupted_intent_can_be_recovered_after_reopen(){let temp=tempfile::tempdir().unwrap();let path=temp.path().join("test.db");{let db=Database::open(&path).unwrap();db.0.lock().unwrap().execute("INSERT INTO changes(optimization_id,previous_value,new_value,status) VALUES('visual.menu_animation','1','0','pending')",[]).unwrap();}let db=Database::open(&path).unwrap();let store=Fake::new();*store.value.lock().unwrap()=Some(0);restore_with(&db,1,&store).unwrap();assert_eq!(store.read("").unwrap(),Some(1));assert_eq!(db.list("changes").unwrap()[0]["status"],"restored");}
 #[test]fn every_preference_detects_applies_verifies_and_restores(){for id in IDS{let db=Database::open(Path::new(":memory:")).unwrap();let store=Fake::new();assert_eq!(store.read(id).unwrap(),Some(1));let change=apply_with(&db,id,Some(1),&store).unwrap();assert_eq!(store.read(id).unwrap(),Some(0));restore_with(&db,change["id"].as_i64().unwrap(),&store).unwrap();assert_eq!(store.read(id).unwrap(),Some(1));}}
 #[test]fn every_preference_handles_denied_and_stale_requests(){for id in IDS{let db=Database::open(Path::new(":memory:")).unwrap();let store=Fake::new();assert!(apply_with(&db,id,Some(0),&store).is_err());assert!(db.list("changes").unwrap().as_array().unwrap().is_empty());*store.deny.lock().unwrap()=true;assert!(apply_with(&db,id,Some(1),&store).is_err());let saved=db.list("changes").unwrap();assert_eq!(saved[0]["previous_value"],"1");assert_eq!(saved[0]["status"],"failed");assert_eq!(store.read(id).unwrap(),Some(1));}}
 #[test]fn every_preference_rejects_unverified_writes(){for id in IDS{let db=Database::open(Path::new(":memory:")).unwrap();let mut store=Fake::new();store.ignore=true;assert!(apply_with(&db,id,Some(1),&store).is_err());assert_eq!(db.list("changes").unwrap()[0]["status"],"failed");}}
 #[test]fn unavailable_api_blocks_each_preference_before_writing(){struct Unavailable;impl Preferences for Unavailable{fn read(&self,_:&str)->Result<Option<u32>,String>{Err("API not supported by this Windows/session".into())}fn write(&self,_:&str,_:Option<u32>)->Result<(),String>{panic!("Unsupported API must never be written")}}for id in IDS{let db=Database::open(Path::new(":memory:")).unwrap();assert!(apply_with(&db,id,Some(1),&Unavailable).is_err());assert!(db.list("changes").unwrap().as_array().unwrap().is_empty());}}
}

// No IPC endpoint exposes this function. Mutations are limited to a disposable CI runner.
pub fn isolated_roundtrip()->Result<Value,String>{
 if std::env::var("GITHUB_ACTIONS").as_deref()!=Ok("true")||std::env::var("RUNNER_OS").as_deref()!=Ok("Windows"){return Err("Ensaio exclusivo do runner Windows descartável".into())}
 struct RestoreOnExit{ id:&'static str, value:Option<u32> }
 impl Drop for RestoreOnExit{fn drop(&mut self){let _=write(self.id,self.value);}}
 let mut results=Vec::new();for id in IDS{let original=read(id)?;let guard=RestoreOnExit{id,value:original};let outcome:Result<(),String>=(||{let db=Database::open(std::path::Path::new(":memory:"))?;write(id,Some(1))?;let change=apply(&db,id,Some(1))?;if read(id)?!=Some(0){return Err("A API não confirmou a alteração".into())}restore(&db,change["id"].as_i64().ok_or("ID de restauro ausente")?)?;if read(id)?!=Some(1){return Err("A API não confirmou o restauro do diário".into())}Ok(())})();let recovered=write(id,original);if recovered.is_err(){return Err(format!("Restauro final falhou em {id}: {recovered:?}"))}drop(guard);outcome?;results.push(json!({"id":id,"initial":original,"applied":0,"journal_restored":1,"final":read(id)?,"passed":true}));}
 Ok(json!({"passed":true,"tests":results,"method":"SystemParametersInfoW GET/SET; journal apply/verify/restore; original restored","os":sysinfo::System::long_os_version(),"user_windows_modified":false}))
}
